def stack(n_models, n_obs, n_cov):
    m = np.arange(n_models)[:, None, None]
    i = np.arange(n_obs)[None, :, None]
    c = np.arange(n_cov)[None, None, :]
    return 0.4 * np.cos(1.7 * m + 0.31 * i + 0.9 * c) + 0.1 * (m + 1) * np.sin(0.13 * i + c)
